            return False
    return True

def generate_fibonacci(n):
    fib_sequence = [0, 1]
    while len(fib_sequence) < n:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
    return fib_sequence

def prime_fib(n):
    fib_sequence = generate_fibonacci(2 * n)  # Generate enough Fibonacci numbers
    prime_fib_numbers = [num for num in fib_sequence if is_prime(num)]
    return prime_fib_numbers[n - 1]

def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci(n):
        if n <= 0:
            return 0
        elif n == 1:
            return 1
        else:
            a, b = 0, 1
            for _ in range(2, n):
                a, b = b, a + b
            return b

    count = 0
    i = 1
    while count < n:
        i += 1
        if is_prime(fibonacci(i)):
            count += 1

    return fibonacci(i)
